package app.snaptocart.security;
import app.snaptocart.config.AppProperties; import app.snaptocart.user.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.Date; import java.util.UUID;
@Service public class JwtService { private final AppProperties p; private final SecretKey key; public JwtService(AppProperties p){this.p=p;this.key=Keys.hmacShaKeyFor(p.jwtSecret().getBytes(StandardCharsets.UTF_8));} public String issue(User u){Instant now=Instant.now();return Jwts.builder().subject(u.id.toString()).claim("email",u.email).issuedAt(Date.from(now)).expiration(Date.from(now.plus(Duration.ofMinutes(p.accessTokenMinutes())))).signWith(key).compact();} public UUID parse(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());} }
